/*
 * Turn the columnar data into a plain array of objects, once, on load.
 * e.g. PROJECTS[0] === { case_id: "LA00001", state: "Maharashtra", ... }
 * Booleans are stored as 1/0 in the rows above; convert them back to true/false.
 */
window.PROJECTS = (function () {
  var cols = window.PROJECTS_DATA.columns;
  var boolCols = ["sia_conducted", "compensation_disputed", "land_records_digitized", "survey_settlement_pending", "court_case_filed", "case_pending_court", "stay_order_issued", "r_and_r_plan_prepared", "rehabilitation_site_ready", "livelihood_restoration_provided", "awarding_officer_assigned", "delayed"];
  return window.PROJECTS_DATA.rows.map(function (row) {
    var obj = {};
    for (var i = 0; i < cols.length; i++) {
      obj[cols[i]] = row[i];
    }
    boolCols.forEach(function (name) {
      obj[name] = obj[name] === 1;
    });
    return obj;
  });
})();
